import json, glob, os, collections, re, sys
sys.path.insert(0,'scripts/research'); sys.path.insert(0,'scripts')
import retrieval_log
rows=[]
for mf in sorted(glob.glob('retrieval-log/*/manifest.jsonl')):
    sess=mf.split('/')[1]
    for line in open(mf, encoding='utf-8'):
        try: rec=json.loads(line)
        except Exception: continue
        rows.append((sess,rec))
page={}
for s,r in rows:
    p=os.path.join('retrieval-log',s,r.get('artefact',''))
    if r.get('derived') or not os.path.isfile(p): continue
    try: msg=json.load(open(p,encoding='utf-8')).get('message')
    except Exception: continue
    if isinstance(msg,dict) and msg.get('DOI'):
        page.setdefault(r.get('ref_id') or 'NOREF', []).append((msg.get('page'), msg.get('article-number'), msg.get('type'), s, r.get('artefact')))
print("sources with crossref payloads:", len(page))
for k in sorted(page, key=str):
    v=page[k]
    print(k, "payload_page_range=", retrieval_log.payload_page_range(k) if k!='NOREF' else None, v[0][:3])
    # derived texts held and whether they carry page markers
    for s,r in rows:
        if r.get('ref_id')==k and r.get('derived'):
            p=os.path.join('retrieval-log',s,r.get('artefact',''))
            try: txt=open(p,encoding='utf-8',errors='replace').read()
            except Exception: txt=''
            marks=len(re.findall(r'^\s*(?:---\s*)?(?:page|PAGE|\[page)\s*\d+', txt, re.M))
            print("    derived:", s, r.get('artefact'), r.get('content_type'), len(txt), "page-marker-lines:", marks)
print("derived JSON records:", [(s,r.get('artefact'),r.get('ref_id')) for s,r in rows if r.get('derived') and (r.get('content_type') or '').startswith('application/json')][:6])
print("PDF-only sources (held pdf, no derived, no text/html):")
by=collections.defaultdict(list)
for s,r in rows:
    if r.get('ref_id'): by[r['ref_id']].append(r)
for ref,recs in sorted(by.items()):
    cts={(r.get('content_type') or '').split(';')[0] for r in recs}
    if 'application/pdf' in cts and not any(r.get('derived') for r in recs) and not any(c.startswith('text/') for c in cts):
        print("   ", ref, cts, "bodies:", retrieval_log.decodable_body_artefacts(ref))
